def transform(grid):
    R, C = len(grid), len(grid[0])
    cells = {(r, c) for r in range(R) for c in range(C) if grid[r][c] == 8}

    def pieces_at(cell, remaining):
        r, c = cell
        # Prefer 2x2 squares.
        sq = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
        if sq <= remaining:
            yield sq, 1
        # L triominoes, colored by their missing corner.
        for dr in (-1, 0):
            for dc in (-1, 0):
                block = {(r + dr + i, c + dc + j)
                         for i in range(2) for j in range(2)}
                if not block <= remaining:
                    continue
                if len(block) != 4:
                    continue
                for missing, color in [
                    ((0, 0), 2),  # missing top-left
                    ((1, 0), 3),  # missing bottom-left
                    ((0, 1), 4),  # missing top-right
                    ((1, 1), 2),  # missing bottom-right
                ]:
                    tri = block - {(r + dr + missing[0], c + dc + missing[1])}
                    if cell in tri and tri <= remaining:
                        yield tri, color

    def solve(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for shape, color in pieces_at(cell, remaining):
            tail = solve(remaining - shape)
            if tail is not None:
                return [(shape, color)] + tail
        return None

    tiling = solve(cells)
    out = [[0] * C for _ in range(R)]
    if tiling is not None:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
