def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    def candidates(rem, cell):
        r, c = cell
        # Solid 2x2 tiles are color 1.
        for rr in (r - 1, r):
            for cc in (c - 1, c):
                sq = {(rr + dr, cc + dc) for dr in range(2) for dc in range(2)}
                if cell in sq and sq <= rem:
                    yield sq, 1

        # L triominoes. Color depends on the missing corner.
        colors = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 2}
        for rr in (r - 1, r):
            for cc in (c - 1, c):
                box = {(rr + dr, cc + dc) for dr in range(2) for dc in range(2)}
                for missing, color in colors.items():
                    tri = box - {(rr + missing[0], cc + missing[1])}
                    if cell in tri and tri <= rem:
                        yield tri, color

    def search(rem):
        if not rem:
            return []
        cell = min(rem)
        for shape, color in candidates(rem, cell):
            rest = search(rem - shape)
            if rest is not None:
                return [(shape, color)] + rest
        return None

    tiling = search(cells)
    out = [[0] * w for _ in range(h)]
    if tiling:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
